package statsquarter

import (
	"errors"
	"sort"
)

func sortedCopy(xs []int64) []int64 {
	s := append([]int64(nil), xs...)
	sort.Slice(s, func(i, j int) bool { return s[i] < s[j] })
	return s
}

func floorDivMod(a, b int64) (int64, int64) {
	q, r := a/b, a%b
	if r != 0 && (r < 0) != (b < 0) {
		q--
		r += b
	}
	return q, r
}

func MeanRound(xs []int64) (int64, error) {
	if len(xs) == 0 {
		return 0, errors.New("empty")
	}
	var sum int64
	for _, x := range xs {
		sum += x
	}
	n := int64(len(xs))
	q, r := floorDivMod(sum, n)
	switch {
	case 2*r < n:
		return q, nil
	case 2*r > n:
		return q + 1, nil
	}
	if q%2 == 0 {
		return q, nil
	}
	return q + 1, nil
}

func Median2(xs []int64) (int64, error) {
	if len(xs) == 0 {
		return 0, errors.New("empty")
	}
	s := sortedCopy(xs)
	n := len(s)
	if n%2 == 1 {
		return 2 * s[n/2], nil
	}
	return s[n/2-1] + s[n/2], nil
}

func PercentileNr(xs []int64, p int64) (int64, error) {
	if len(xs) == 0 || p < 1 || p > 100 {
		return 0, errors.New("bad input")
	}
	s := sortedCopy(xs)
	rank := (p*int64(len(s)) + 99) / 100
	return s[rank-1], nil
}

func ModeSmallest(xs []int64) (int64, bool) {
	if len(xs) == 0 {
		return 0, false
	}
	counts := map[int64]int{}
	for _, x := range xs {
		counts[x]++
	}
	best, bestCount := int64(0), 0
	for v, c := range counts {
		if c > bestCount || (c == bestCount && v < best) {
			best, bestCount = v, c
		}
	}
	return best, true
}

func Spread(xs []int64) (int64, error) {
	if len(xs) == 0 {
		return 0, errors.New("empty")
	}
	lo, hi := xs[0], xs[0]
	for _, x := range xs {
		if x < lo {
			lo = x
		}
		if x > hi {
			hi = x
		}
	}
	return hi - lo, nil
}

func Histogram(xs []int64, lo, width, bins int64) ([]int64, error) {
	if width <= 0 || bins <= 0 {
		return nil, errors.New("bad buckets")
	}
	out := make([]int64, bins)
	for _, x := range xs {
		if x < lo {
			continue
		}
		i := (x - lo) / width
		if i < bins {
			out[i]++
		}
	}
	return out, nil
}

func TrimmedSum(xs []int64, k int64) (int64, error) {
	if k < 0 || 2*k > int64(len(xs)) {
		return 0, errors.New("bad k")
	}
	s := sortedCopy(xs)
	var sum int64
	for _, x := range s[k : int64(len(s))-k] {
		sum += x
	}
	return sum, nil
}

