def mean_round(xs):
    if not xs:
        raise ValueError("empty")
    n = len(xs)
    q, r = divmod(sum(xs), n)
    if 2 * r < n:
        return q
    if 2 * r > n:
        return q + 1
    return q if q % 2 == 0 else q + 1


def median2(xs):
    if not xs:
        raise ValueError("empty")
    s = sorted(xs)
    n = len(s)
    if n % 2:
        return 2 * s[n // 2]
    return s[n // 2 - 1] + s[n // 2]


def percentile_nr(xs, p):
    if not xs or p < 1 or p > 100:
        raise ValueError("bad input")
    s = sorted(xs)
    rank = (p * len(s) + 99) // 100
    return s[rank - 1]


def mode_smallest(xs):
    counts = {}
    for x in xs:
        counts[x] = counts.get(x, 0) + 1
    if not counts:
        return None
    best = max(counts.values())
    return min(k for k, v in counts.items() if v == best)


def spread(xs):
    if not xs:
        raise ValueError("empty")
    return max(xs) - min(xs)


def histogram(xs, lo, width, bins):
    if width <= 0 or bins <= 0:
        raise ValueError("bad buckets")
    out = [0] * bins
    for x in xs:
        if x < lo:
            continue
        i = (x - lo) // width
        if i < bins:
            out[i] += 1
    return out


def trimmed_sum(xs, k):
    if k < 0 or 2 * k > len(xs):
        raise ValueError("bad k")
    s = sorted(xs)
    return sum(s[k:len(s) - k])

