  if (2 * r < n) return q;
  if (2 * r > n) return q + 1;
  return q % 2 === 0 ? q : q + 1;
}

function median2(xs) {
  if (xs.length === 0) throw new Error('empty');
  const s = [...xs].sort(byValue);
  const n = s.length;
  return n % 2 ? 2 * s[(n - 1) / 2] : s[n / 2 - 1] + s[n / 2];
}

